// === Tab: mySketch ===
const SCL = 4, // scale for level of details
	N = 3 * SCL, // distance between lines / raster
	NF = 32 * N, // noise factor, reciproc 
	F1 = 102 / N, F2 = 54 / N; // factor for line len (1) and spacing (2)

const PENS = [ // not in use
	{clr: "darkorange", f: 1},
	{clr: "silver", f: 2},
	{clr: "darkred", f: 0.2},
];

let pal, svgGrps;

function setup() {
	createCanvas(297 * SCL, 210 * SCL);
	frameRate(30);
	loop();
	// seed
	const seed = ~~random(1234567); // 1095092
	console.log(`seed: ${seed}`)
	noiseSeed(seed);
	// palette
	pal = random(palettes);
	/*
	svgGrps = Array(PENS.length)
	let sumF = 0;
	for (let i = 0; i < PENS.length; i++) sumF += PENS[i].f;
